#include <set>
#include <vector>

int main() {
    const std::vector<int> visits = {42, 7, 42, 19, 7, 3};
    std::set<int> ids(visits.begin(), visits.end());
    ids.insert(5);
    ids.insert(42);  // already in the set, ignored

    std::cout << ids.size() << '\n';
    std::cout << std::boolalpha << "19 visited: " << (ids.count(19) == 1) << '\n';

    ids.erase(7);
    bool first = true;
    for (int id : ids) {
        if (!first) {
            std::cout << ' ';
        }
        std::cout << id;
        first = false;
    }
    std::cout << '\n';
    return 0;
}

