#include <algorithm>
#include <iostream>
#include <iterator>
#include <set>
#include <string>

void printLine(const std::string& label, const std::set<std::string>& names) {
    std::cout << label << ':';
    for (const auto& name : names) {
        std::cout << ' ' << name;
    }
    std::cout << '\n';
}

int main() {
    const std::set<std::string> math = {"ana", "ben", "cy"};
    const std::set<std::string> art = {"ben", "cy", "dee"};

    std::set<std::string> both;
    std::set_intersection(math.begin(), math.end(), art.begin(), art.end(),
                          std::inserter(both, both.begin()));
    std::set<std::string> either;
    std::set_union(math.begin(), math.end(), art.begin(), art.end(),
                   std::inserter(either, either.begin()));
    std::set<std::string> onlyMath;
    std::set_difference(math.begin(), math.end(), art.begin(), art.end(),
                        std::inserter(onlyMath, onlyMath.begin()));

    printLine("both", both);
    printLine("either", either);
    printLine("only math", onlyMath);
    return 0;
}

