#include <iterator>
#include <set>
#include <string>

void printLine(const std::string& label, const std::set<std::string>& skills) {
    std::cout << label << ':';
    for (const auto& skill : skills) {
        std::cout << ' ' << skill;
    }
    std::cout << '\n';
}

int main() {
    const std::set<std::string> required = {"cpp", "git", "linux", "sql"};
    const std::set<std::string> candidate = {"git", "python", "sql"};

    std::set<std::string> matched;
    std::set_intersection(required.begin(), required.end(), candidate.begin(), candidate.end(),
                          std::inserter(matched, matched.begin()));
    std::set<std::string> missing;
    std::set_difference(required.begin(), required.end(), candidate.begin(), candidate.end(),
                        std::inserter(missing, missing.begin()));
    std::set<std::string> combined;
    std::set_union(required.begin(), required.end(), candidate.begin(), candidate.end(),
                   std::inserter(combined, combined.begin()));

    printLine("matched", matched);
    printLine("missing", missing);
    printLine("all", combined);
    return 0;
}

